verus! {

    // splitlines: for a non‐empty vector of Strings `a`,
    // returns a Vec<Vec<String>> of the same length,
    // and each inner Vec<String> is non‐empty.
    fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>>
        requires
            a.len() > 0,
        ensures
            result.len() == a.len(),
            // every inner list is non‐empty
            forall(|i: usize| i < result.len() ==> result[i].len() > 0),
    {
        let mut res: Vec<Vec<String>> = Vec::new();
        let mut i: usize = 0;
        // iterate over all indices of `a`
        while i < a.len()
            invariant
                // progress
                i <= a.len(),
                // we've pushed exactly `i` vectors so far
                res.len() == i,
                // each pushed vector is non‐empty
                forall(|j: usize| j < res.len() ==> res[j].len() > 0),
            decreases a.len() - i,
        {
            // make a singleton list containing a[i]
            let mut inner: Vec<String> = Vec::new();
            inner.push(a[i].clone());
            res.push(inner);

            i += 1;
        }

        res
    }
}

